def _collect_referenced_extras(
    self, item: MarkerAtom | MarkerLogical, extras: set[NormalizedName]
) -> None:
    """Recursively collect extra names from the marker tree."""
    import ast

    if item == "and" or item == "or":
        return
    if isinstance(item, list):
        for sub in item:
            self._collect_referenced_extras(sub, extras)
    elif isinstance(item, tuple):
        lhs, op, rhs = item
        lhs_is_extra = isinstance(lhs, Variable) and lhs.value == "extra"
        rhs_is_extra = isinstance(rhs, Variable) and rhs.value == "extra"
        if lhs_is_extra and isinstance(rhs, Value):
            extras.add(canonicalize_name(rhs.value))
        elif rhs_is_extra and isinstance(lhs, Value):
            extras.add(canonicalize_name(lhs.value))
        elif isinstance(rhs, Variable) and rhs.value == "extras":
            if isinstance(lhs, Value):
                extras.add(canonicalize_name(lhs.value))
